You should use Rust's standard library and idiomatic Rust coding practices to implement the solution.

### Solution:
```rust
use std::collections::HashMap;

// Define a struct to represent an encryption scheme
struct EncryptionScheme {
    name: String,
    properties: HashMap<String, String>,
}

impl EncryptionScheme {
    // Create a new encryption scheme with a given name and properties
    fn new(name: String, properties: HashMap<String, String>) -> Self {
        EncryptionScheme { name, properties }
    }

    // Get the name of the encryption scheme
    fn get_name(&self) -> &str {
        &self.name
    }

    // Get the properties of the encryption scheme
    fn get_properties(&self) -> &HashMap<String, String> {
        &self.properties
    }
}

// Define a struct to manage the collection of encryption schemes
struct EncryptionManager {
    schemes: HashMap<String, EncryptionScheme>,
}

impl EncryptionManager {
    // Create a new encryption manager
    fn new() -> Self {
        EncryptionManager {
            schemes: HashMap::new(),
        }
    }

    // Add a new encryption scheme to the manager
    fn add_scheme(&mut self, scheme: EncryptionScheme) {
        self.schemes.insert(scheme.name.clone(), scheme);
    }

    // Retrieve the properties of a specific encryption scheme by its name
    fn get_scheme_properties(&self, name: &str) -> Option<&HashMap<String, String>> {
        self.schemes.get(name).map(|scheme| scheme.get_properties())
    }

    // List all available encryption schemes along with their names and properties
    fn list_schemes(&self) {
        for (index, scheme) in self.schemes.values().enumerate() {
            println!("{}: {} - {:?}", index, scheme.get_name(), scheme.get_properties());
        }
    }
}

fn main() {
    // Create a new encryption manager
    let mut manager = EncryptionManager::new();

    // Add some sample encryption schemes
    let scheme1 = EncryptionScheme::new(
        "AES".to_string(),
        [("key_length".to_string(), "128 bits".to_string())]
            .iter()
            .cloned()
            .collect(),
    );
    let scheme2 = EncryptionScheme::new(
        "RSA".to_string(),
        [("key_length".to_string(), "2048 bits".to_string())]
            .iter()
            .cloned()
            .collect(),
    );

    manager.add_scheme(scheme1);
    manager.add_scheme(scheme2);

    // Retrieve and print the properties of a specific encryption scheme
    if let Some(properties) = manager.get_scheme_properties("AES") {
        println!("AES properties: {:?}", properties);
    }

    // List all available encryption schemes
    manager.list_schemes();
}
