                        } else if value.predictedEndTranslation.width > geometry.size.width / 2 {
                            self.index = max(self.index - 1, 0)
                        }
                        withAnimation {
                            self.isGestureActive = false
                            self.offset = -geometry.size.width * CGFloat(self.index)
                        }
                    }
            )
        }
    }
}

