### Problem:
You are tasked with creating a dependency resolution algorithm for a package manager. The package manager uses a configuration file to define targets and their dependencies. Each target can depend on other targets within the same package or on products in packages which this package depends on.

Your task is to implement a function that takes in the configuration file as input and resolves the dependencies for each target, ensuring that all dependencies are satisfied.

The configuration file is represented as an array of tuples, where each tuple contains the name of the target, its dependencies, and whether it is a test target or not. The format of the configuration file is as follows:
```swift
let configuration: [(name: String, dependencies: [String], isTestTarget: Bool)] = [
    (name: "Target1", dependencies: ["Dependency1", "Dependency2"], isTestTarget: false),
    (name: "Target2", dependencies: ["Dependency3"], isTestTarget: true),
    // ... more targets
]
```
The function signature is:
```swift
func resolveDependencies(configuration: [(name: String, dependencies: [String], isTestTarget: Bool)]) -> [String: [String]]
```
Where `configuration` is the input configuration file and the output is a dictionary where the key is the target name and the value is an array of its resolved dependencies.

For example, given the following configuration:
```swift
let configuration: [(name: String, dependencies: [String], isTestTarget: Bool)] = [
    (name: "Target1", dependencies: ["Dependency1", "Dependency2"], isTestTarget: false),
    (name: "Target2", dependencies: ["Dependency3"], isTestTarget: true),
    (name: "Dependency1", dependencies: [], isTestTarget: false),
    (name: "Dependency2", dependencies: ["Dependency1"], isTestTarget: false),
    (name: "Dependency3", dependencies: ["Dependency1", "Dependency2"], isTestTarget: false)
]
```
The resolved dependencies should be:
```swift
[
    "Target1": ["Dependency1", "Dependency2"],
    "Target2": ["Dependency3"],
    "Dependency1": [],
    "Dependency2": ["Dependency1"],
    "Dependency3": ["Dependency1", "Dependency2"]
]
```

### Solution:
```swift
func resolveDependencies(configuration: [(name: String, dependencies: [String], isTestTarget: Bool)]) -> [String: [String]] {
    var dependencyMap: [String: [String]] = [:]

    for target in configuration {
        dependencyMap[target.name] = target.dependencies
    }

    var resolvedDependencies: [String: [String]] = [:]

    func resolve(target: String, visited: Set<String>) -> [String] {
        var dependencies: [String] = []

        for dependency in dependencyMap[target] ?? [] {
            if visited.contains(dependency) {
                // Circular dependency detected
                // Handle the error or return an empty array based on the requirements
                return []
            }

            let newVisited = visited.union([dependency])
            let resolved = resolve(target: dependency, visited: newVisited)
            dependencies.append(contentsOf: resolved)
        }

        resolvedDependencies[target] = dependencies
        return dependencies
    }

    for target in configuration {
        if !target.isTestTarget {
            _ = resolve(target: target.name, visited: Set())
        }
    }

    return resolvedDependencies
}
```

