    "b": 25,
    "c": 35
}
```

### Solution:
```python
def calculate_average_snapshot(snapshot_dict: dict) -> dict:
    average_snapshot = {}
    num_snapshots = len(snapshot_dict)

    for snapshot in snapshot_dict.values():
        for key, value in snapshot.items():
            if key in average_snapshot:
                average_snapshot[key] += value
            else:
                average_snapshot[key] = value

    for key in average_snapshot:
