function extractAttributes(template: string): Record<string, string> {
  const attributeRegex = /(\S+)=["']?((?:.(?!["']?\s+(?:\S+)=|[>"']))+.)["']?/g;
  const attributes: Record<string, string> = {};

  let match;
  while ((match = attributeRegex.exec(template)) !== null) {
