```rust
fn k_nearest(points: &[(f64, f64)], pt: (f64, f64), k: usize) -> Vec<(f64, f64)> {
    let mut distances: Vec<(f64, usize)> = points
        .iter()
        .enumerate()
        .map(|(i, &p)| (euclidean_distance(pt, p), i))
        .collect();

    distances.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());

    distances
        .iter()
        .take(k)
        .map(|&(_, i)| points[i])
        .collect()
}

fn euclidean_distance(p1: (f64, f64), p2: (f64, f64)) -> f64 {
    ((p2.0 - p1.0).powi(2) + (p2.1 - p1.1).powi(2)).sqrt()
}
