def calculate_signatures(adata, cell_type_labels, data_loc, save_path=None):
    signatures = {}
    for cell_type in cell_type_labels:
        if data_loc == "X":
            signatures[cell_type] = adata[adata.obs[cell_type_labels] == cell_type].X.mean(axis=0)
