def parse_input_file(file_path: str, field_spec: dict) -> list:
    records = []
    with open(file_path, 'r') as file:
        for line in file:
            record = {}
            for section, fields in field_spec.items():
                for field_name, (start, end), data_type in fields:
                    value = line[start:end+1].strip()
                    if data_type == str:
                        record[field_name] = value
                    elif data_type == int:
