### Solution:
```javascript
function findDuplicateStyles(styledComponents) {
  const styleMap = new Map();

  styledComponents.forEach(({ componentName, styles }) => {
    if (styleMap.has(styles)) {
      styleMap.get(styles).push(componentName);
    } else {
      styleMap.set(styles, [componentName]);
    }
  });

  const duplicateStyles = [];
  styleMap.forEach((components, styles) => {
    if (components.length > 1) {
      duplicateStyles.push({ sharedStyles: styles, components });
    }
  });

  return duplicateStyles;
