import torch

def cat_props(props):
    new_props = {}
    for key, val in props.items():
        if isinstance(val, list) and all(isinstance(item, torch.Tensor) for item in val):
            if len(val[0].shape) == 0:  # Check if the tensor has a shape of length 0 (scalar)
