### Problem:
You are tasked with implementing a matrix struct in Swift that supports basic matrix operations. The matrix struct should have the following functionalities:

1. A method `get` that retrieves the value at a specific row and column in the matrix.
2. A mutating method `set` that updates the value at a specific row and column in the matrix.
3. A static property `identity` that returns the identity matrix of the same size.
4. An overloaded operator `*` that multiplies two matrices together.
5. An overloaded operator `*` that multiplies a matrix by a column vector.

Your task is to implement the matrix struct with the specified functionalities and ensure that the operations are performed correctly.

### Solution:
```swift
struct Matrix {
    let rows: Int
    let columns: Int
    var grid: [Float]

    init(rows: Int, columns: Int) {
        self.rows = rows
        self.columns = columns
        grid = Array(repeating: 0.0, count: rows * columns)
    }

    func indexIsValid(row: Int, column: Int) -> Bool {
        return row >= 0 && row < rows && column >= 0 && column < columns
    }

    func indexFor(row: Int, column: Int) -> Int {
        return row * columns + column
    }

    func get(at row: Int, _ column: Int) -> Float {
        assert(indexIsValid(row: row, column: column), "Index out of range")
        return grid[indexFor(row: row, column: column)]
    }

    mutating func set(at row: Int, _ column: Int, _ value: Float) {
        assert(indexIsValid(row: row, column: column), "Index out of range")
        grid[indexFor(row: row, column: column)] = value
    }

    static var identity: Matrix {
        let identityMatrix = Matrix(rows: 2, columns: 2)
        identityMatrix.set(at: 0, 0, 1.0)
        identityMatrix.set(at: 1, 1, 1.0)
        return identityMatrix
    }

    static func *(a: Matrix, b: Matrix) -> Matrix {
        assert(a.columns == b.rows, "Matrix dimensions not compatible for multiplication")
        let result = Matrix(rows: a.rows, columns: b.columns)
        for i in 0..<a.rows {
            for j in 0..<b.columns {
                var sum: Float = 0
                for k in 0..<a.columns {
                    sum += a.get(at: i, k) * b.get(at: k, j)
                }
                result.set(at: i, j, sum)
            }
        }
        return result
    }

    static func *(a: Matrix, b: ColumnVector) -> ColumnVector {
        assert(a.columns == b.count, "Matrix and column vector dimensions not compatible for multiplication")
        var result = ColumnVector(size: a.rows)
        for i in 0..<a.rows {
            var sum: Float = 0
            for j in 0..<a.columns {
                sum += a.get(at: i, j) * b[j]
            }
            result[i] = sum
        }
        return result
    }
}

struct ColumnVector {
    var elements: [Float]

    init(size: Int) {
        elements = Array(repeating: 0.0, count: size)
    }

    subscript(index: Int) -> Float {
        get {
            return elements[index]
        }
        set(newValue) {
            elements[index] = newValue
        }
    }

    var count: Int {
        return elements.count
    }
}
```

This solution provides a Swift implementation of a matrix struct with the specified functionalities, including methods for retrieving and updating values, generating an identity matrix, and performing matrix multiplication with both another matrix and a column vector. The solution also includes a separate struct for representing column vectors.

