use std::mem;

trait Endian {
    fn get(&self) -> f64;
    fn set(&mut self, value: f64);
}

impl Endian for f64 {
    fn get(&self) -> f64 {
        unsafe { mem::transmute(mem::transmute::<f64, u64>(*self).to_le()) }
    }

    fn set(&mut self, value: f64) {
        *self = unsafe { mem::transmute(mem::transmute::<f64, u64>(value).to_le()) };
    }
}

