### Solution:
```rust
struct CustomArray<T> {
    data: Vec<T>,
}

impl<T: Clone> CustomArray<T> {
    fn new(size: usize, default: T) -> Self {
        CustomArray {
            data: vec![default; size],
        }
    }

    fn get(&self, index: usize) -> Option<&T> {
        self.data.get(index)
    }

    fn set(&mut self, index: usize, value: T) -> Option<&T> {
        if let Some(elem) = self.data.get_mut(index) {
            *elem = value;
            Some(elem)
        } else {
            None
        }
    }

    fn as_slice(&self) -> &[T] {
        &self.data
    }
}

